namespace docking.actions.dialog;

using static ghidra.util.HTMLUtilities;











using docking;
using docking.action;
using docking.actions;
using docking.widgets.list;
using docking.widgets.searchlist;
using docking.widgets.searchlist;
using generic.theme.GThemeDefaults;
using generic.theme.GThemeDefaults.Colors;
using ghidra.util;
